public static void main(String[] args){
    var sc = new Scanner(System.in);
    String word = sc.nextLine();
    int[] some = new int[26];
    for(int x = 0; x < word.length(); x++){
        some[word.charAt(x) - 'a']++;
    }
    long totalSwaps = (long)word.length() * (word.length() - 1) / 2;
    long nonDistinctSwaps = 0;
    for(int n : some){
        if(n >= 2){
            nonDistinctSwaps += (long)n * (n - 1) / 2;
        }
    }
    long result = totalSwaps - nonDistinctSwaps;
    System.out.println(result);
}
